import React, { useEffect, useRef } from 'react';

const RainbowCursor = () => {
  const canvasRef = useRef(null);
  const particlesRef = useRef([]);
  const hueRef = useRef(0);
  const cursorRef = useRef({ x: window.innerWidth / 2, y: window.innerHeight / 2 });
  const lastPosRef = useRef({ x: cursorRef.current.x, y: cursorRef.current.y });

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    let animationFrameId;

    class RainbowParticle {
      constructor(x, y, hue, angle) {
        this.x = x;
        this.y = y;
        this.size = Math.random() * 12 + 6;
        this.hue = hue + (Math.random() - 0.5) * 30;
        this.life = 1;
        this.decay = Math.random() * 0.015 + 0.008;

        const speed = Math.random() * 3 + 1;
        this.speedX = Math.cos(angle) * speed;
        this.speedY = Math.sin(angle) * speed;

        this.rotation = Math.random() * Math.PI * 2;
        this.rotationSpeed = (Math.random() - 0.5) * 0.2;
      }

      update() {
        this.x += this.speedX;
        this.y += this.speedY;
        this.speedX *= 0.95;
        this.speedY *= 0.95;
        this.life -= this.decay;
        this.size *= 0.97;
        this.rotation += this.rotationSpeed;
      }

      draw(ctx) {
        ctx.save();
        ctx.globalAlpha = this.life * 0.8;
        ctx.translate(this.x, this.y);
        ctx.rotate(this.rotation);

        const gradient = ctx.createRadialGradient(0, 0, 0, 0, 0, this.size * 2);
        gradient.addColorStop(0, `hsla(${this.hue}, 100%, 70%, 1)`);
        gradient.addColorStop(0.3, `hsla(${this.hue}, 100%, 60%, 0.8)`);
        gradient.addColorStop(0.6, `hsla(${this.hue}, 100%, 50%, 0.4)`);
        gradient.addColorStop(1, `hsla(${this.hue}, 100%, 40%, 0)`);

        ctx.fillStyle = gradient;
        ctx.beginPath();
        ctx.arc(0, 0, this.size * 2, 0, Math.PI * 2);
        ctx.fill();

        ctx.restore();
      }
    }

    const resizeCanvas = () => {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    };

    const handleMouseMove = (e) => {
      cursorRef.current.x = e.clientX;
      cursorRef.current.y = e.clientY;

      const dx = cursorRef.current.x - lastPosRef.current.x;
      const dy = cursorRef.current.y - lastPosRef.current.y;
      const distance = Math.sqrt(dx * dx + dy * dy);

      const particleCount = Math.min(Math.floor(distance / 2) + 3, 15);

      for (let i = 0; i < particleCount; i++) {
        const angle = (Math.PI * 2 * i) / particleCount + Math.random() * 0.5;
        particlesRef.current.push(
          new RainbowParticle(cursorRef.current.x, cursorRef.current.y, hueRef.current, angle)
        );
      }

      hueRef.current += 1.5;
      if (hueRef.current > 360) hueRef.current = 0;

      lastPosRef.current.x = cursorRef.current.x;
      lastPosRef.current.y = cursorRef.current.y;
    };

    const animate = () => {
      ctx.fillStyle = 'rgba(0, 0, 0, 0.08)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      ctx.save();
      ctx.globalAlpha = 0.6;
      const cursorGlow = ctx.createRadialGradient(
        cursorRef.current.x,
        cursorRef.current.y,
        0,
        cursorRef.current.x,
        cursorRef.current.y,
        50
      );
      cursorGlow.addColorStop(0, `hsla(${hueRef.current}, 100%, 70%, 0.8)`);
      cursorGlow.addColorStop(0.5, `hsla(${hueRef.current + 30}, 100%, 60%, 0.4)`);
      cursorGlow.addColorStop(1, `hsla(${hueRef.current + 60}, 100%, 50%, 0)`);
      ctx.fillStyle = cursorGlow;
      ctx.beginPath();
      ctx.arc(cursorRef.current.x, cursorRef.current.y, 50, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();

      for (let i = particlesRef.current.length - 1; i >= 0; i--) {
        particlesRef.current[i].update();
        particlesRef.current[i].draw(ctx);

        if (particlesRef.current[i].life <= 0) {
          particlesRef.current.splice(i, 1);
        }
      }

      if (particlesRef.current.length > 500) {
        particlesRef.current = particlesRef.current.slice(-500);
      }

      animationFrameId = requestAnimationFrame(animate);
    };

    resizeCanvas();
    window.addEventListener('resize', resizeCanvas);
    document.addEventListener('mousemove', handleMouseMove);
    animate();

    return () => {
      window.removeEventListener('resize', resizeCanvas);
      document.removeEventListener('mousemove', handleMouseMove);
      cancelAnimationFrame(animationFrameId);
    };
  }, []);

  return (
    <canvas
      ref={canvasRef}
      style={{
        position: 'fixed',
        top: 0,
        left: 0,
        width: '100%',
        height: '100%',
        pointerEvents: 'none',
        zIndex: 9999,
        mixBlendMode: 'screen'
      }}
    />
  );
};

export default RainbowCursor;
